"""wire-1108: one smallest shape per family slot per supported engine, generated by the production generator."""

import importlib.util
import json
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location(
    "fullcmp_manifest", ROOT / "scripts/research/fullcmp_manifest.py"
)
fm = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(fm)


def _json(rows):
    return [json.loads(json.dumps(r, sort_keys=True)) for r in rows]


@pytest.fixture(scope="module")
def rows():
    return _json(fm.wire_1108_rows())


@pytest.fixture(scope="module")
def real_by_id():
    path = Path(fm.REAL_MANIFEST)
    if not path.exists():
        pytest.skip("real manifest not present on this host")
    return {
        json.loads(line)["id"]: json.loads(line)
        for line in path.read_text().splitlines()
        if line.strip()
    }


def test_every_supported_engine_gets_each_slot_unless_census_rules_it_out(rows):
    supported = [
        e
        for e in fm.ENGINE_IDS
        if fm.ENGINES[e]["supported"] and e not in fm.WIRE_1108_SKIP
    ]
    assert supported, "no supported engines"
    for _slot, _batch, kw in fm.WIRE_1108_SHAPES:
        sp = fm.spec(**kw, reps=fm.WIRE_1108_REPS)
        for eng in supported:
            status, _why = fm.cell_status(eng, sp)
            ids = [
                r["id"]
                for r in rows
                if r["engine"] == eng
                and r["sweep"] == sp["sweep"]
                and r["ctx"] == sp["ctx"]
                and r["prompt_kind"] == sp["kind"]
                and r["out_len"] == sp["out"]
                and r["conc"] == sp["conc"]
            ]
            if status == fm.UNV:
                assert len(ids) == 1, f"{eng} {sp['sweep']} must have exactly one row"
            else:
                assert ids == [], f"{eng} {sp['sweep']} is {status}; no row"


def test_rows_are_the_production_generator_output(rows):
    for r in rows:
        ctx_sp = next(
            fm.spec(**kw, reps=fm.WIRE_1108_REPS)
            for _s, _b, kw in fm.WIRE_1108_SHAPES
            if kw["sweep"] == r["sweep"]
            and kw.get("ctx") == r["ctx"]
            and kw.get("kind", "code") == r["prompt_kind"]
            and kw.get("out", 512) == r["out_len"]
            and kw.get("conc", 1) == r["conc"]
            and kw.get("thinking", "off") == r["thinking"]
            and kw.get("sampling", "greedy") == r["sampling"]
            and kw.get("media", "none") == r["media"]
            and kw.get("turns", "single") == r["turns"]
        )
        regen = fm._cell_row(r["engine"], r["batch"], ctx_sp)
        regen.pop("_work_min")
        regen.pop("_group", None)
        regen["est_gpu_min"] = r["est_gpu_min"]
        assert _json([regen])[0] == r, f"{r['id']} differs from the generator"


def test_every_row_is_one_rep(rows):
    assert rows and all(r["reps"] == 1 for r in rows)


def test_shapes_present_in_the_real_manifest_match_it_except_reps_and_estimate(
    rows, real_by_id
):
    matched = 0
    for r in rows:
        real = real_by_id.get(r["id"])
        if real is None:
            continue
        matched += 1
        # request arguments only: the real matrix's budget cuts (status, reason) do not apply to this run
        drop = ("reps", "est_gpu_min", "status", "reason")
        a = {k: v for k, v in r.items() if k not in drop}
        b = {k: v for k, v in real.items() if k not in drop}
        assert a == b, f"{r['id']} differs from the real manifest row"
    assert matched > 0


def test_lmstudio_and_ollama_are_not_selected(rows):
    engines = {r["engine"] for r in rows}
    for e in ("lmstudio", "ollama"):
        if e in fm.ENGINES and not fm.ENGINES[e]["supported"]:
            assert e not in engines


def test_family_smoke_writes_the_generated_rows(tmp_path):
    out = tmp_path / "wire_1108_manifest.jsonl"
    assert fm.main(["--family-smoke", "--out", str(out)]) == 0
    written = [json.loads(line) for line in out.read_text().splitlines()]
    assert written == _json(fm.wire_1108_rows())
